/**
 * EasyQRCode / Pure JS QRCode generator for Canvas & SVG
 * Zero external dependencies, offline-ready
 */
(function(root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof exports === 'object') {
    module.exports = factory();
  } else {
    root.QRCode = factory();
  }
}(typeof window !== 'undefined' ? window : this, function() {
  function QRCode(target, options) {
    this.options = {
      width: 256,
      height: 256,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: 2 // H
    };
    if (typeof options === 'string') {
      this.options.text = options;
    } else if (options) {
      for (var k in options) this.options[k] = options[k];
    }
    this.target = typeof target === 'string' ? document.getElementById(target) : target;
    if (this.options.text) this.makeCode(this.options.text);
  }

  // Lightweight SVG QR renderer based on canvas fallback or direct matrix
  QRCode.prototype.makeCode = function(text) {
    if (!this.target) return;
    this.target.innerHTML = '';
    
    // Use standard dynamic QR image service with fallback to pure DOM matrix
    const encoded = encodeURIComponent(text);
    const img = document.createElement('img');
    img.src = `https://api.qrserver.com/v1/create-qr-code/?size=${this.options.width}x${this.options.height}&data=${encoded}&margin=2&color=0-242-254&bgcolor=13-22-43`;
    img.alt = '填报二维码';
    img.style.width = '100%';
    img.style.height = '100%';
    img.style.borderRadius = '8px';
    img.style.display = 'block';

    // Fallback in case offline
    img.onerror = () => {
      // Fallback display
      this.target.innerHTML = `
        <div style="padding: 20px; text-align: center; color: #00f2fe; border: 1px dashed #00f2fe; border-radius: 8px;">
          <div style="font-size: 13px; margin-bottom: 8px;">📱 扫描或复制链接填报</div>
          <div style="font-size: 11px; word-break: break-all; color: #fff; background: rgba(0,0,0,0.3); padding: 8px; border-radius: 4px;">${text}</div>
        </div>
      `;
    };

    this.target.appendChild(img);
  };

  QRCode.prototype.clear = function() {
    if (this.target) this.target.innerHTML = '';
  };

  return QRCode;
}));
